 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.userData.handlers = {};

  const timelines = [];
  const disposables = [];

  const colorsSrc = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
    ...colorsSrc,
  };

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const atlasRegion = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRegion.w / atlasRegion.h;
  const height = 1.0;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  disposables.push(geometry);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
  });
  disposables.push(material);

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        const fullW = tex.image?.width || atlasRegion.w;
        const fullH = tex.image?.height || atlasRegion.h;

        const repeatX = atlasRegion.w / fullW;
        const repeatY = atlasRegion.h / fullH;
        const offsetX = atlasRegion.x / fullW;
        const offsetY = 1 - (atlasRegion.y + atlasRegion.h) / fullH;

        const atlasUV = uv()
          .mul(vec2(repeatX, repeatY))
          .add(vec2(offsetX, offsetY));

        material.colorNode = texture(tex, atlasUV);
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  for (const item of textItems) {
    if (!item || !item.text) continue;

    const fontSize = item.typography?.fontSize ?? 39;
    const textRole = item.role ?? 'headline';
    const textColor = textRole === 'caption' ? colors.ink : colors.paper;

    const textMesh = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: textColor,
      align: 'left',
    });

    textMesh.position.set(-width * 0.42, -0.05, 0.02);
    group.add(textMesh);
  }

  plane.onBeforeRender = (renderer, scene, camera) => {
    if (camera) {
      group.quaternion.copy(camera.quaternion);
    }
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (ctx.primitives[primitive.name]) {
      const result = ctx.primitives[primitive.name](group, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (result?.cleanup) disposables.push(result.cleanup);
    }
  }

  group.userData.cleanup = () => {
    plane.onBeforeRender = null;

    timelines.forEach((t) => {
      try {
        t.kill();
      } catch (_e) {}
    });

    disposables.forEach((d) => {
      try {
        if (typeof d === 'function') d();
        else d.dispose();
      } catch (_e) {}
    });
  };

  return group;
}

export default createNode;
